#!/usr/bin/env node
/** Probe: does the map fill its container right after switching to "nur Karte"? */
import { spawn } from 'node:child_process';
import { writeFile, mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const url = 'http://127.0.0.1:8787/';
const port = 9444;
const binary = '/usr/bin/chromium';
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-'));
const child = spawn(binary, ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`, '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,1000', 'about:blank'], { stdio: ['ignore', 'ignore', 'pipe'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) { for (let i = 0; i < 40; i++) { try { const res = await fetch(`http://127.0.0.1:${port}${p}`); if (res.ok) return res.json(); } catch {} await sleep(250); } throw new Error('no cdp'); }
await endpoint('/json/version');
const targets = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(targets.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map();
ws.onmessage = (m) => { const d = JSON.parse(m.data); if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); } };
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const evalJs = async (expression) => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.result?.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails));
  return r.result?.result?.value;
};
await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url });
await sleep(5000);
const measure = () => evalJs(`(() => {
  const map = document.querySelector('#map');
  const layer = map && map.querySelector('.map-layer');
  const wrap = document.querySelector('.app-mapwrap');
  const grid = document.querySelector('.app-grid');
  const r = (el) => el ? { w: Math.round(el.clientWidth), h: Math.round(el.clientHeight), x: Math.round(el.getBoundingClientRect().left) } : null;
  const tiles = [...document.querySelectorAll('.map-layer img, .map-tile img, #map img')].map((i) => ({ x: Math.round(i.getBoundingClientRect().left), w: Math.round(i.getBoundingClientRect().width) }));
  return { view: document.querySelector('#app')?.className, grid: r(grid), wrap: r(wrap), map: r(map), layer: r(layer), tileCount: tiles.length, tileBounds: tiles.length ? { minX: Math.min(...tiles.map(t=>t.x)), maxX: Math.max(...tiles.map(t=>t.x+t.w)) } : null };
})()`);
console.log('before:', JSON.stringify(await measure()));
// click "nur Karte"
const ok = await evalJs(`(() => { const b = [...document.querySelectorAll('button')].find((x) => (x.textContent||'').trim() === 'nur Karte'); if (!b) return false; b.click(); return true; })()`);
console.log('clicked nur Karte:', ok);
for (const wait of [50, 200, 400, 900, 1600]) {
  await sleep(wait);
  console.log(`after +${wait}ms:`, JSON.stringify(await measure()));
}
const shot = await send('Page.captureScreenshot', { format: 'png' });
await writeFile('/tmp/probe-maponly.png', Buffer.from(shot.result.data, 'base64'));
child.kill();

