/**
 * Worldwide place names for the search box — normalisation of the Photon
 * response (an OpenStreetMap geocoder, https://photon.komoot.io/).
 *
 * Why a second gazetteer: the swisstopo SearchServer is the *Swiss* gazetteer.
 * It answers a foreign query with its closest Swiss neighbours — measured
 * 2026-10-19: `Kairo` → “Coira (GR)”, `New York` → “New York Weg 1, 3638
 * Blumenstein”, `Rom` → “Fliessgewaesser Rom (GR)”. The catalogue itself is not
 * Swiss-only (it carries world maps from 1546 to 1914), so the box needs a
 * worldwide source next to it. Photon is the documented OSM search-as-you-type
 * API; its terms ask for fair use and state that availability is not guaranteed
 * (“extensive usage will be throttled”), which is exactly why the Worker caches
 * each query and the client keeps working without it.
 *
 * This module is pure: it turns one Photon GeoJSON payload into the compact
 * `{ label, lat, lon, bbox, kind, country }` contract the client already uses for
 * swisstopo results. Nothing is inferred — a feature without a finite position is
 * dropped instead of being placed somewhere plausible.
 */

/** Upper bound the endpoint accepts; the client asks for fewer. */
export const MAX_WORLD_RESULTS = 8;

/** The attribution the client must be able to show (ODbL: © OpenStreetMap). */
export const WORLD_ATTRIBUTION = 'Ortsnamen: © OpenStreetMap-Mitwirkende (ODbL), Geokodierung über Photon (komoot)';

/**
 * German kind word per OSM value/type. Deliberately small and literal: a value
 * that is not listed keeps the upstream `type` (or “Ort”), because inventing a
 * category for an unknown tag would be worse than naming the class verbatim.
 */
const KIND_BY_OSM_VALUE = {
  city: 'Stadt',
  town: 'Stadt',
  village: 'Dorf',
  hamlet: 'Weiler',
  municipality: 'Gemeinde',
  suburb: 'Quartier',
  neighbourhood: 'Quartier',
  quarter: 'Quartier',
  locality: 'Ortsteil',
  country: 'Land',
  state: 'Region',
  province: 'Region',
  region: 'Region',
  county: 'Bezirk',
  district: 'Kreis',
  borough: 'Bezirk',
  administrative: 'Verwaltungseinheit',
  peak: 'Berg',
  mountain_range: 'Gebirge',
  volcano: 'Berg',
  island: 'Insel',
  islet: 'Insel',
  water: 'Gewässer',
  lake: 'See',
  river: 'Fluss',
  stream: 'Bach',
  forest: 'Wald',
  wood: 'Wald',
  station: 'Bahnhof',
  university: 'Universität',
  school: 'Schule',
  museum: 'Museum',
  castle: 'Schloss',
  church: 'Kirche',
  houses: 'Häuser',
  house: 'Adresse',
};

const KIND_BY_TYPE = {
  house: 'Adresse',
  street: 'Strasse',
  locality: 'Ortsteil',
  district: 'Kreis',
  city: 'Stadt',
  county: 'Bezirk',
  state: 'Region',
  country: 'Land',
  other: 'Ort',
};

/** One German kind word for a Photon feature; never throws on missing fields. */
export function photonKind(properties = {}) {
  const value = String(properties.osm_value ?? '').toLowerCase();
  const type = String(properties.type ?? '').toLowerCase();
  return KIND_BY_OSM_VALUE[value] || KIND_BY_TYPE[type] || (type ? type : 'Ort');
}

/** One label part, trimmed and without the upstream's own “NULL” placeholder. */
function part(value) {
  const text = String(value ?? '').trim();
  return text.length > 0 && text.length <= 90 ? text : '';
}

/**
 * `Name, Ort, Region, Land` with repeated parts removed (case-insensitively):
 * OSM repeats the city in `state` for city-states and the name in `city` for
 * districts, and “Kairo, Kairo, Ägypten” reads like a bug. The name always
 * comes first, and at most four parts are joined.
 */
export function photonLabel(properties = {}) {
  const name = part(properties.name);
  const city = part(properties.city) || part(properties.locality);
  const region = part(properties.state) || part(properties.county);
  const country = part(properties.country);
  const parts = [];
  for (const candidate of [name, city, region, country]) {
    if (!candidate) continue;
    const folded = candidate.toLowerCase();
    if (parts.some((seen) => seen.toLowerCase() === folded)) continue;
    parts.push(candidate);
  }
  const label = parts.join(', ');
  return label.length > 90 ? `${label.slice(0, 87)}…` : label;
}

/**
 * Photon's `extent` is `[west, north, east, south]` (decimal degrees). It is
 * only passed on when it really is a box: a degenerate or reversed extent would
 * make “fit the map to this place” zoom somewhere wrong, so it becomes `null`.
 */
export function photonBbox(extent) {
  if (!Array.isArray(extent) || extent.length < 4) return null;
  const [west, north, east, south] = extent.map(Number);
  if (![west, north, east, south].every(Number.isFinite)) return null;
  if (west >= east || south >= north) return null;
  if (west < -180 || east > 180 || south < -90 || north > 90) return null;
  return { west, south, east, north };
}

/**
 * One Photon GeoJSON payload as the search-box contract. Features without a
 * usable position are dropped (the client filters on finite coordinates too, but
 * the endpoint should not promise a place it cannot point at).
 */
export function normalizePhoton(payload, limit = MAX_WORLD_RESULTS) {
  const cap = Math.min(Math.max(Number(limit) || MAX_WORLD_RESULTS, 1), MAX_WORLD_RESULTS);
  const features = Array.isArray(payload?.features) ? payload.features : [];
  const results = [];
  for (const feature of features) {
    if (results.length >= cap) break;
    const coordinates = feature?.geometry?.coordinates;
    if (!Array.isArray(coordinates) || coordinates.length < 2) continue;
    const lon = Number(coordinates[0]);
    const lat = Number(coordinates[1]);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
    if (lat < -90 || lat > 90 || lon < -180 || lon > 180) continue;
    const properties = feature.properties ?? {};
    const label = photonLabel(properties);
    if (!label) continue;
    results.push({
      label,
      lat,
      lon,
      bbox: photonBbox(properties.extent),
      kind: photonKind(properties),
      country: part(properties.country) || null,
      countryCode: part(properties.countrycode) || null,
    });
  }
  return { results, source: 'openstreetmap', attribution: WORLD_ATTRIBUTION };
}

