/** Hosts the proxy may talk to, and the path prefixes allowed per host. */
export const ALLOWLIST = [
  { host: 'api3.geo.admin.ch', prefixes: ['/rest/services/api/SearchServer'] },
  // The worldwide place search (maps-2): OpenStreetMap via the documented
  // Photon API. Terms: fair use, no availability guarantee — the Worker caches
  // every query for a day and the client keeps working without it.
  { host: 'photon.komoot.io', prefixes: ['/api/'] },

/**
 * GET /api/search/world?q=&limit= — worldwide place names from OpenStreetMap
 * via Photon, the second gazetteer next to swisstopo's Swiss one.
 *
 * Proxied for three reasons: the browser keeps `connect-src 'self'`, the query
 * is bounded and cached for a day per query string (Photon's terms ask for fair
 * use and do not promise availability), and the response is normalised into the
 * shape `/api/search/places` already returns. An upstream failure is answered
 * with 502 and is *not* cached, so a temporary outage cannot be frozen into the
 * edge cache for 24 h.
 */
async function searchWorld(request, ctx) {
  const url = new URL(request.url);
  const q = (url.searchParams.get('q') || '').trim();
  const limit = Math.min(Math.max(Number(url.searchParams.get('limit') || 6), 1), MAX_WORLD_RESULTS);
  if (q.length < 2 || q.length > 120) {
    return json({ error: 'query_too_short', detail: 'q must be 2..120 characters', results: [] }, { status: 400 });
  }
  const cache = caches.default;
  const cacheKey = new Request(`${url.origin}/api/search/world?q=${encodeURIComponent(q)}&limit=${limit}`, { method: 'GET' });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  const target = new URL('https://photon.komoot.io/api/');
  target.searchParams.set('q', q);
  target.searchParams.set('limit', String(limit));
  target.searchParams.set('lang', 'de');
  let res;
  try {
    res = await upstream(target.toString(), { accept: 'application/json' });
  } catch (err) {
    return json({ error: 'upstream_unreachable', detail: String(err && err.message), results: [] }, { status: 502 });
  }
  if (!res.ok) return json({ error: 'upstream_error', status: res.status, results: [] }, { status: 502 });
  let payload;
  try {
    payload = await res.json();
  } catch {
    return json({ error: 'upstream_invalid_json', results: [] }, { status: 502 });
  }
  const out = json({ ...normalizePhoton(payload, limit), attribution: WORLD_ATTRIBUTION }, { headers: { 'cache-control': 'public, max-age=86400' } });
  ctx.waitUntil(cache.put(cacheKey, out.clone()));
  return out;
}

