const MIN_CHARS = 2;

/**
 * The two folded spellings of a place name’s first segment.
 *
 * “Rheinau (ZH)” is the *same* name as “Rheinau, Deutschland”, and a Swiss
 * gazetteer result habitually carries its canton in brackets, so the bracket
 * content is removed before comparing. `foldDigraph` + `foldPlain` come from
 * `records.js`, so the place box and the list filter agree on “Zuerich”.”
 */
function nameKeys(label) {
  const first = String(label ?? '')
    .split(',')[0]
    .replace(/\([^)]*\)/g, ' ')
    .trim();
  if (!first) return [];
  return [foldPlain(foldDigraph(first)), foldPlain(first)];
}

/** The folded spellings of the typed query (empty query → no keys). */
function queryKeys(query) {
  const text = String(query ?? '').trim();
  if (!text) return [];
  return [foldPlain(foldDigraph(text)), foldPlain(text)].filter((key, index, all) => key && all.indexOf(key) === index);
}

/**
 * How well one suggestion answers the typed words:
 * `3` the name *is* the query, `2` it starts with it, `1` it contains it,
 * `0` no match (the gazetteer’s own fuzzy answer — “Kairo” → “Coira (GR)”).
 */
export function nameMatchScore(query, label) {
  const keys = typeof query === 'string' ? queryKeys(query) : query ?? [];
  let best = 0;
  for (const key of keys) {
    for (const name of nameKeys(label)) {
      if (name === key) best = Math.max(best, 3);
      else if (name.startsWith(key)) best = Math.max(best, 2);
      else if (name.includes(key)) best = Math.max(best, 1);
    }
  }
  return best;
}

/** Same name at (almost) the same spot — the Swiss entry wins, the OSM copy is dropped. */
function samePlace(a, b) {
  const aNames = nameKeys(a.label);
  const bNames = nameKeys(b.label);
  if (!aNames.some((name) => bNames.includes(name))) return false;
  if (![a.lat, a.lon, b.lat, b.lon].every(Number.isFinite)) return false;
  return Math.abs(a.lat - b.lat) <= 0.25 && Math.abs(a.lon - b.lon) <= 0.25;
}

/**
 * Merge and rank the two gazetteers’ answers for the box.
 *
 * Both sources are asked in parallel, and the ranking decides what the visitor
 * sees first instead of a fixed “Swiss first”:
 *
 *   10 × match class (3 name, 2 prefix, 1 contains, 0 fuzzy) + 5 for swisstopo
 *
 * so the Swiss gazetteer wins every tie (it is the collection’s home), while a
 * real foreign match (“Kairo, Ägypten”, “New York, Vereinigte Staaten”) is
 * placed above the Swiss sound-alike or address it is confused with. Nothing is
 * hidden: a fuzzy Swiss answer stays in the list, at the bottom. A worldwide
 * entry that is the *same name at the same place* as a Swiss one is dropped,
 * because that duplicate carries no new information.
 */
export function mergePlaceSuggestions(query, swiss = [], world = []) {
  const keys = queryKeys(query);
  const entries = [];
  (swiss ?? []).forEach((item, index) => entries.push({ item: { ...item, group: 'swisstopo' }, bonus: 5, index }));
  (world ?? []).forEach((item, index) =>
    entries.push({ item: { ...item, group: 'openstreetmap', origin: `OpenStreetMap${item.kind ? ` · ${item.kind}` : ''}` }, bonus: 0, index: index + (swiss ?? []).length }),
  );
  const ranked = entries
    .map((entry) => ({ ...entry, score: nameMatchScore(keys, entry.item.label) * 10 + entry.bonus }))
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .map((entry) => entry.item);
  const items = [];
  for (const item of ranked) {
    if (item.group === 'openstreetmap' && items.some((kept) => kept.group === 'swisstopo' && samePlace(kept, item))) continue;
    items.push(item);
  }
  return {
    items,
    places: items.filter((item) => item.group === 'swisstopo'),
    world: items.filter((item) => item.group === 'openstreetmap'),
  };
}

