/**
 * One bounded JSON GET against our own Worker. The HTTP status becomes part of
 * the error, so the status line can name “HTTP 502” instead of an English
 * developer string (see `errorReason`).
 */
async function jsonGet(url, signal) {
  const res = await fetch(url, { signal });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

async function suggest(query) {
  state.controller?.abort();
  state.controller = new AbortController();
  const { signal } = state.controller;
  setStatus(status, 'Orte werden gesucht …');
  form.setAttribute('aria-busy', 'true');
  // The record search always joins the list (last, so a real place stays the
  // default choice); it is the only suggestion when no place matches.
  const records = datasetSuggestion(ctx.data.records, query, ctx.store.getState());
  try {
    // Both gazetteers are asked at once: swisstopo answers for Switzerland,
    // OpenStreetMap (Photon, `/api/search/world`) for the rest of the world —
    // the catalogue carries world maps from 1546 to 1914, and the Swiss
    // gazetteer answers “Kairo” with “Coira (GR)”. Each failure is reported on
    // its own: one outage must not hide the other source’s answer.
    const [swissResult, worldResult] = await Promise.allSettled([
      jsonGet(`/api/search/places?q=${encodeURIComponent(query)}&limit=8`, signal),
      query.length >= 3 ? jsonGet(`/api/search/world?q=${encodeURIComponent(query)}&limit=6`, signal) : Promise.reject(new Error('query_too_short')),
    ]);
    if (signal.aborted) return;
    const usable = (data) => (data?.results ?? []).filter((item) => Number.isFinite(item.lat) && Number.isFinite(item.lon));
    const swiss = swissResult.status === 'fulfilled' ? usable(swissResult.value) : [];
    const world = worldResult.status === 'fulfilled' ? usable(worldResult.value) : [];
    // A 2-character query is not a fault of the world search; do not report it.
    const worldError = worldResult.status === 'rejected' && worldResult.reason?.message !== 'query_too_short' ? errorReason(worldResult.reason) : '';
    const swissError = swissResult.status === 'rejected' ? errorReason(swissResult.reason) : '';
    const merged = mergePlaceSuggestions(query, swiss, world);
    if (merged.items.length === 0) {
      const local = localFallback(query);
      const combined = records ? [records, ...local] : local;
      open(combined, 'lokal');
      setStatus(status, statusText({ records, local, swissError, worldError }));
      return;
    }
    open(records ? [...merged.items, records] : merged.items, merged.world.length > 0 ? 'swisstopo + OpenStreetMap' : 'swisstopo');
    setStatus(status, statusText({ places: merged.places, world: merged.world, records, swissError, worldError }));
  } catch (err) {
    if (err?.name === 'AbortError') return;
    const local = localFallback(query);
    const combined = records ? [records, ...local] : local;
    open(combined, 'lokal');
    setStatus(
      status,
      local.length > 0 || records
        ? `Ortssuche nicht erreichbar (${errorReason(err)}) – Vorschläge aus den Datensätzen.`
        : `Ortssuche derzeit nicht erreichbar (${errorReason(err)}).`,
    );
  } finally {
    form.setAttribute('aria-busy', 'false');
  }
}

/**
 * One honest sentence about what the list offers: places found per gazetteer,
 * record matches, or neither, and which source failed. The counts come from the
 * suggestions that are really shown, so a deduplicated worldwide entry is not
 * counted twice.
 */
function statusText({ places = [], world = [], records = null, local = [], swissError = '', worldError = '' } = {}) {
  const parts = [];
  if (swissError) parts.push(`Ortssuche (swisstopo) nicht erreichbar (${swissError})`);
  if (places.length > 0) parts.push(`${places.length} Ortsvorschläge (swisstopo)`);
  else if (!swissError) parts.push('Kein Ortsvorschlag (swisstopo)');
  if (world.length > 0) parts.push(`${world.length} weltweit (OpenStreetMap)`);
  else if (worldError && !swissError) parts.push(`weltweite Suche nicht erreichbar (${worldError})`);
  if (records) parts.push(`${records.origin} zu „${records.query}“`);
  else if (local.length > 0) parts.push(`${local.length} Titelvorschläge aus dem Bestand`);
  if (parts.length === 0) return 'Kein Ort und kein Titeltreffer gefunden.';
  return `${parts.join(' · ')}. Mit ↓/↑ wählen, Enter bestätigen.`;
}

