/**
 * Worldwide place search (maps-2, 7-67).
 *
 * The search box used to have one gazetteer: swisstopo's SearchServer, which
 * only knows Switzerland. Measured against the live service on 2026-10-19:
 *
 *   Kairo     -> “Coira (GR)”                            (Chur!)
 *   New York  -> “New York Weg 1, 3638 Blumenstein”      (a Swiss address)
 *   Rom       -> “Fliessgewaesser Rom (GR) – Val Müstair”
 *
 * The catalogue is not Swiss-only (it carries world maps from 1546 to 1914), so
 * `/api/search/world` adds OpenStreetMap place names through the documented
 * Photon API, and `mergePlaceSuggestions()` decides which of the two answers
 * the box shows first. These tests pin the two halves: the payload
 * normalisation (pure, no network) and the ranking (pure).
 */
import test from 'node:test';
import assert from 'node:assert/strict';

import { mergePlaceSuggestions, nameMatchScore } from '../public/app/search.js';
import { MAX_WORLD_RESULTS, normalizePhoton, photonBbox, photonKind, photonLabel } from '../src/worker/worldsearch.js';

/** A trim of the real response for `q=Kairo&limit=3&lang=de` (2026-10-19). */
const KAIRO = {
  type: 'FeatureCollection',
  features: [
    {
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [31.2357257, 30.0443879] },
      properties: { osm_type: 'R', osm_id: 5466227, osm_key: 'place', osm_value: 'city', type: 'city', name: 'Kairo', state: 'Kairo', country: 'Ägypten', countrycode: 'EG', extent: [31.2200331, 30.3209168, 31.9090054, 29.7483062] },
    },
    {
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [31.5621651, 30.0332516] },
      properties: { osm_type: 'R', osm_id: 4103336, osm_key: 'boundary', osm_value: 'administrative', type: 'state', name: 'Kairo', country: 'Ägypten', countrycode: 'EG', extent: [31.214555, 30.3209168, 31.9090054, 29.7483062] },
    },
  ],
};

/** A trim of the real response for `q=New York&limit=1&lang=de` (2026-10-19). */
const NEW_YORK = {
  type: 'FeatureCollection',
  features: [
    {
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [-74.0060152, 40.7127281] },
      properties: { osm_type: 'R', osm_key: 'place', osm_value: 'city', type: 'city', name: 'New York', state: 'New York', country: 'Vereinigte Staaten von Amerika', countrycode: 'US', extent: [-74.258843, 40.91763, -73.700233, 40.476578] },
    },
  ],
};

/** What swisstopo's SearchServer really answers for the same queries. */
const COIRA = { label: 'Coira (GR)', origin: 'gg25', lat: 46.83235549926758, lon: 9.516542434692383, bbox: null };
const ZUERICH_CH = { label: 'Zürich (ZH)', origin: 'gg25', lat: 47.3772, lon: 8.5411, bbox: { west: 8.44688, south: 47.32275, east: 8.62595, north: 47.43414 } };
const NEW_YORK_WEG = { label: 'New York Weg 1, 3638 Blumenstein', origin: 'gg25', lat: 46.743350982666016, lon: 7.515712, bbox: null };

test('a Photon feature becomes the same suggestion shape the swisstopo results use', () => {
  const { results, source, attribution } = normalizePhoton(KAIRO, 6);
  assert.equal(source, 'openstreetmap');
  assert.match(attribution, /OpenStreetMap/);
  const [cairo] = results;
  assert.equal(cairo.label, 'Kairo, Ägypten', 'the repeated governorate is not doubled');
  assert.equal(cairo.kind, 'Stadt');
  assert.equal(cairo.lat, 30.0443879);
  assert.equal(cairo.lon, 31.2357257);
  assert.deepEqual(cairo.bbox, { west: 31.2200331, south: 29.7483062, east: 31.9090054, north: 30.3209168 });
  assert.equal(cairo.countryCode, 'EG');
});

test('the extent is only passed on when it really is a box', () => {
  assert.deepEqual(photonBbox([8, 47, 9, 46]), { west: 8, south: 46, east: 9, north: 47 });
  for (const broken of [null, [], [8, 47, 9], ['a', 'b', 'c', 'd'], [9, 47, 8, 46], [8, 46, 9, 47], [8, 47, 9, 91]]) {
    assert.equal(photonBbox(broken), null, `${JSON.stringify(broken)} is not a box`);
  }
});

test('a feature without a usable position is dropped, not guessed', () => {
  const payload = {
    features: [
      { geometry: { coordinates: [8.5] }, properties: { name: 'Ohne Position' } },
      { geometry: null, properties: { name: 'Ohne Geometrie' } },
      { geometry: { coordinates: ['x', 'y'] }, properties: { name: 'Unsinn' } },
      { geometry: { coordinates: [8.54, 47.38] }, properties: { name: 'Zürich' } },
    ],
  };
  const { results } = normalizePhoton(payload, 6);
  assert.deepEqual(results.map((result) => result.label), ['Zürich']);
});

test('the result count is capped (the endpoint must not promise more than it shows)', () => {
  const many = { features: Array.from({ length: 20 }, (_, i) => ({ geometry: { coordinates: [8 + i / 10, 47] }, properties: { name: `Ort ${i}`, country: 'Schweiz' } })) };
  assert.equal(normalizePhoton(many, 3).results.length, 3);
  assert.equal(normalizePhoton(many, 99).results.length, MAX_WORLD_RESULTS);
});

test('the German kind comes from the OSM value, and an unknown tag keeps the upstream type', () => {
  assert.equal(photonKind({ osm_value: 'peak', type: 'other' }), 'Berg');
  assert.equal(photonKind({ osm_value: 'country', type: 'country' }), 'Land');
  assert.equal(photonKind({ osm_value: 'station', type: 'house' }), 'Bahnhof');
  assert.equal(photonKind({ type: 'street' }), 'Strasse');
  assert.equal(photonKind({ type: 'mystery' }), 'mystery');
  assert.equal(photonKind({}), 'Ort');
});

test('the label repeats no part and stays readable', () => {
  assert.equal(photonLabel({ name: 'Kairo', state: 'Kairo', country: 'Ägypten' }), 'Kairo, Ägypten');
  assert.equal(photonLabel({ name: 'New York', state: 'New York', country: 'Vereinigte Staaten von Amerika' }), 'New York, Vereinigte Staaten von Amerika');
  assert.equal(photonLabel({ name: 'Zürich Hauptbahnhof', city: 'Zürich', state: 'Zürich', country: 'Schweiz' }), 'Zürich Hauptbahnhof, Zürich, Schweiz');
  assert.equal(photonLabel({ name: '', country: 'Schweiz' }), 'Schweiz');
  assert.equal(photonLabel({}), '');
});

test('the name match class is what the typo-tolerance is built on', () => {
  assert.equal(nameMatchScore('Kairo', 'Kairo, Ägypten'), 3);
  assert.equal(nameMatchScore('Zuerich', 'Zürich (ZH)'), 3, 'the canton bracket is not part of the name');
  assert.equal(nameMatchScore('Zurich', 'Zürich (ZH)'), 3);
  assert.equal(nameMatchScore('Rhein', 'Rheinau (ZH)'), 2);
  assert.equal(nameMatchScore('York', 'New York Weg 1, 3638 Blumenstein'), 1);
  assert.equal(nameMatchScore('Kairo', 'Coira (GR)'), 0);
});

test('a real foreign match is ranked above the Swiss sound-alike (Kairo vs Coira)', () => {
  const world = normalizePhoton(KAIRO, 6).results;
  const { items, places, world: worldItems } = mergePlaceSuggestions('Kairo', [COIRA], world);
  assert.equal(places.length, 1, 'the fuzzy Swiss answer stays in the list');
  assert.equal(worldItems.length, 2);
  assert.equal(items.length, 3);
  assert.match(items[0].label, /^Kairo, Ägypten$/, 'the worldwide city is first');
  assert.equal(items[0].group, 'openstreetmap');
  assert.match(items[0].origin, /OpenStreetMap · Stadt/);
  assert.equal(items.at(-1).label, 'Coira (GR)', 'the sound-alike is last, not hidden');
  for (const item of items) assert.ok(Number.isFinite(item.lat) && Number.isFinite(item.lon));
});

test('a worldwide entry that duplicates a Swiss place is dropped, and the Swiss one wins the tie', () => {
  const zurich = { label: 'Zürich, Schweiz', kind: 'Stadt', lat: 47.3744489, lon: 8.5410422, bbox: { west: 8.4480182, south: 47.3202184, east: 8.6254529, north: 47.434665 } };
  const { items, places, world } = mergePlaceSuggestions('Zürich', [ZUERICH_CH], [zurich]);
  assert.equal(world.length, 0, 'the same name at the same spot adds nothing');
  assert.equal(items.length, 1);
  assert.equal(items[0].label, 'Zürich (ZH)');
  assert.equal(places[0].group, 'swisstopo');
});

test('a worldwide city outranks the Swiss address that shares its name (New York)', () => {
  const world = normalizePhoton(NEW_YORK, 6).results;
  const { items } = mergePlaceSuggestions('New York', [NEW_YORK_WEG], world);
  assert.equal(items[0].label, 'New York, Vereinigte Staaten von Amerika');
  assert.equal(items.at(-1).label, 'New York Weg 1, 3638 Blumenstein');
  const [first] = items;
  assert.deepEqual(first.bbox, { west: -74.258843, south: 40.476578, east: -73.700233, north: 40.91763 }, 'the extent is what “fit the map” uses');
});

test('an empty or failing world search leaves the swisstopo list exactly as it was', () => {
  const { items, places, world } = mergePlaceSuggestions('Rheinau', [ZUERICH_CH, { label: 'Rheinau (ZH)', origin: 'gg25', lat: 47.6437, lon: 8.6045, bbox: null }], []);
  assert.equal(world.length, 0);
  assert.equal(places.length, 2);
  assert.equal(items[0].label, 'Rheinau (ZH)', 'the exact name stays first');
});

test('without any suggestion the merge returns nothing instead of a placeholder place', () => {
  const { items, places, world } = mergePlaceSuggestions('Xqzwv', [], []);
  assert.deepEqual(items, []);
  assert.deepEqual(places, []);
  assert.deepEqual(world, []);
});

test('the merge never mutates the upstream objects', () => {
  const swiss = [{ label: 'Zürich (ZH)', lat: 47.3772, lon: 8.5411 }];
  const worldItems = normalizePhoton(KAIRO, 2).results;
  mergePlaceSuggestions('Zürich', swiss, worldItems);
  assert.equal('group' in swiss[0], false);
  assert.equal('origin' in worldItems[0], false);
});

