test('GET /api/search/world validates input, asks Photon politely and normalises the answer', async () => {
  const tooShort = await call('/api/search/world?q=z');
  assert.equal(tooShort.status, 400);
  assert.equal((await tooShort.json()).error, 'query_too_short');
  assert.equal(upstreamCalls.length, 0, 'invalid input never reaches the upstream');

  upstreamResponder = () =>
    new Response(
      JSON.stringify({
        type: 'FeatureCollection',
        features: [
          {
            type: 'Feature',
            geometry: { type: 'Point', coordinates: [31.2357257, 30.0443879] },
            properties: { name: 'Kairo', state: 'Kairo', country: 'Ägypten', countrycode: 'EG', osm_value: 'city', type: 'city', extent: [31.2200331, 30.3209168, 31.9090054, 29.7483062] },
          },
        ],
      }),
      { status: 200, headers: { 'content-type': 'application/json' } },
    );
  const res = await call('/api/search/world?q=Kairo&limit=3');
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.source, 'openstreetmap');
  assert.match(body.attribution, /OpenStreetMap/);
  assert.deepEqual(body.results.map((r) => r.label), ['Kairo, Ägypten']);
  assert.equal(body.results[0].kind, 'Stadt');
  assert.deepEqual(body.results[0].bbox, { west: 31.2200331, south: 29.7483062, east: 31.9090054, north: 30.3209168 });
  assert.match(res.headers.get('cache-control'), /max-age=86400/, 'a query is cached for a day, not refetched per keystroke');

  const upstreamUrl = new URL(upstreamCalls.at(-1).url);
  assert.equal(upstreamUrl.hostname, 'photon.komoot.io');
  assert.equal(upstreamUrl.pathname, '/api/');
  assert.equal(upstreamUrl.searchParams.get('q'), 'Kairo');
  assert.equal(upstreamUrl.searchParams.get('lang'), 'de');
  assert.equal(upstreamUrl.searchParams.get('limit'), '3');
  assert.match(upstreamCalls.at(-1).init.headers['user-agent'], /zurich-maps/);

  const again = await call('/api/search/world?q=Kairo&limit=3');
  assert.equal(again.status, 200);
  assert.equal(upstreamCalls.length, 1, 'the second identical query comes from the edge cache');
});

test('an unreachable worldwide place search is a 502 that is not cached as an answer', async () => {
  upstreamResponder = () => new Response('rate limited', { status: 429 });
  const res = await call('/api/search/world?q=Bhutan&limit=3');
  assert.equal(res.status, 502);
  assert.equal((await res.json()).error, 'upstream_error');
  const retry = await call('/api/search/world?q=Bhutan&limit=3');
  assert.equal(retry.status, 502);
  assert.equal(upstreamCalls.length, 2, 'a throttled upstream is retried instead of cached for 24 h');
});

