export function normalizePhoton(payload, limit = MAX_WORLD_RESULTS) {
  const cap = Math.min(Math.max(Number(limit) || MAX_WORLD_RESULTS, 1), MAX_WORLD_RESULTS);
  const features = Array.isArray(payload?.features) ? payload.features : [];
  const results = [];
  const seen = new Set();
  for (const feature of features) {
    if (results.length >= cap) break;
    const coordinates = feature?.geometry?.coordinates;
    if (!Array.isArray(coordinates) || coordinates.length < 2) continue;
    const lon = Number(coordinates[0]);
    const lat = Number(coordinates[1]);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
    if (lat < -90 || lat > 90 || lon < -180 || lon > 180) continue;
    const properties = feature.properties ?? {};
    const label = photonLabel(properties);
    if (!label) continue;
    // “Kairo” is the city *and* its governorate: two entries with the same label
    // and different extents read like a duplicate in the list, so the first (the
    // one Photon ranks higher) is kept. Different places keep different labels,
    // because `photonLabel` names the region and the country.
    const key = label.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    results.push({
      label,
      lat,
      lon,
      bbox: photonBbox(properties.extent),
      kind: photonKind(properties),
      country: part(properties.country) || null,
      countryCode: part(properties.countrycode) || null,
    });
  }
  return { results, source: 'openstreetmap', attribution: WORLD_ATTRIBUTION };
}

