#!/usr/bin/env node
/** Probe the worldwide place search in the rendered app (maps-2, 7-67). */
import { spawn } from 'node:child_process';
import { writeFile, mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const BASE = 'http://127.0.0.1:8787';
const port = 9447;
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-'));
const child = spawn('/usr/bin/chromium', ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`, '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,1000', 'about:blank'], { stdio: ['ignore', 'ignore', 'pipe'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) { for (let i = 0; i < 40; i++) { try { const res = await fetch(`http://127.0.0.1:${port}${p}`); if (res.ok) return res.json(); } catch {} await sleep(250); } throw new Error('no cdp'); }
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const consoleErrors = [];
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
  else if (d.method === 'Runtime.consoleAPICalled' && d.params.type === 'error') consoleErrors.push(d.params.args.map((a) => a.value ?? a.description).join(' '));
};
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const evalJs = async (expression) => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.result?.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails).slice(0, 400));
  return r.result?.result?.value;
};
const waitFor = async (expression, timeout = 12000, label = '') => {
  const started = Date.now();
  for (;;) {
    const value = await evalJs(expression);
    if (value) return value;
    if (Date.now() - started > timeout) throw new Error(`timeout waiting for ${label || expression}`);
    await sleep(150);
  }
};

await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: `${BASE}/` });
await waitFor(`document.querySelectorAll('#result-list > *').length > 0`, 25000, 'results');

const type = async (text) => {
  await evalJs(`(() => { const i = document.querySelector('#place-input'); i.value = ''; i.focus(); i.dispatchEvent(new Event('input', { bubbles: true })); return true; })()`);
  for (const ch of text) {
    await send('Input.dispatchKeyEvent', { type: 'keyDown', text: ch });
    await send('Input.dispatchKeyEvent', { type: 'keyUp', text: ch });
    await sleep(60);
  }
};
const board = () => evalJs(`(() => ({
  items: [...document.querySelectorAll('#place-suggestions li button')].map((b) => ({ text: b.querySelector('span')?.textContent ?? b.textContent, type: b.querySelector('.zh-suggestions__type')?.textContent ?? '' })),
  status: document.querySelector('#place-status')?.textContent || '',
  hidden: document.querySelector('#place-suggestions')?.hidden,
}))()`);

for (const query of ['Kairo', 'Rheinau', 'Zürich', 'Xqzwv']) {
  await type(query);
  await sleep(1400);
  const result = await board();
  console.log(`\n### ${query}\n${JSON.stringify(result, null, 1).slice(0, 1200)}`);
}

// Kairo: choose the first suggestion and inspect the map state.
await type('Kairo');
await sleep(1500);
await evalJs(`document.querySelector('#place-suggestions li button')?.click(); true`);
await sleep(1200);
const chosen = await evalJs(`(() => ({
  url: location.search,
  input: document.querySelector('#place-input')?.value,
  chip: document.querySelector('#place-action button')?.textContent ?? null,
  chipPressed: document.querySelector('#place-action button')?.getAttribute('aria-pressed') ?? null,
  status: document.querySelector('#place-status')?.textContent || '',
}))()`);
console.log('\n### chosen Kairo\n' + JSON.stringify(chosen, null, 1));
const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
await writeFile('/tmp/probe-world-kairo.png', Buffer.from(shot.result.data, 'base64'));

// The point filter chip now counts records whose extent covers Cairo.
await evalJs(`document.querySelector('#place-action button')?.click(); true`);
await sleep(1200);
const filtered = await evalJs(`(() => ({ url: location.search, count: document.querySelector('#result-count')?.textContent || '', rows: document.querySelectorAll('#result-list > *').length }))()`);
console.log('\n### point filter\n' + JSON.stringify(filtered, null, 1));

// Keyboard: ArrowDown + Enter on a foreign query picks a place (not the keyword filter).
await send('Page.navigate', { url: `${BASE}/` });
await waitFor(`document.querySelectorAll('#result-list > *').length > 0`, 25000, 'results again');
await type('Sahara');
await sleep(1500);
await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'ArrowDown', code: 'ArrowDown', windowsVirtualKeyCode: 40 });
await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'ArrowDown', code: 'ArrowDown', windowsVirtualKeyCode: 40 });
await sleep(200);
const active = await evalJs(`document.querySelector('#place-suggestions button[aria-selected="true"]')?.textContent ?? null`);
await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13 });
await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13 });
await sleep(1000);
const keyboard = await evalJs(`(() => ({ active: ${JSON.stringify('x')}, url: location.search, input: document.querySelector('#place-input')?.value }))()`);
console.log('\n### keyboard Sahara\n' + JSON.stringify({ ...keyboard, highlighted: active }, null, 1));

console.log('\nconsole errors:', JSON.stringify(consoleErrors.slice(0, 5)));
child.kill();

