/**
 * The two folded spellings of a place name, for the two labelling habits:
 *
 *  - OpenStreetMap/Photon writes “Name, Ort, Land” (name first);
 *  - the swisstopo SearchServer writes “Kategorie Name (Kanton) - Gemeinde”
 *    (“Ort Rheinau (ZH) - Rheinau”, “Gebaeude Zürich-Albisgütli 25m (ZH) - …”).
 *
 * So two candidates are compared: the first comma segment without brackets, and
 * the same segment with its leading category word dropped when the label uses
 * swisstopo’s “ - ” pattern. Whichever matches better counts, which keeps a
 * fuzzy gazetteer answer (“Coira (GR)” for “Kairo”) honest while a Swiss
 * “Rheinau” really is the same name as the German “Rheinau”.
 *
 * `foldDigraph` + `foldPlain` come from `records.js`, so the place box and the
 * list filter agree on “Zuerich”.”
 */
function nameKeys(label) {
  const first = String(label ?? '')
    .split(',')[0]
    .trim();
  if (!first) return [];
  const candidates = [first];
  if (/ - /.test(first)) {
    const words = first.split(' - ')[0].trim().split(/\s+/);
    if (words.length > 1) candidates.push(words.slice(1).join(' '));
  }
  const keys = [];
  for (const candidate of candidates) {
    const name = candidate.replace(/\([^)]*\)/g, ' ').trim();
    if (!name) continue;
    for (const key of [foldPlain(foldDigraph(name)), foldPlain(name)]) if (key && !keys.includes(key)) keys.push(key);
  }
  return keys;
}

