+    'the place box reaches beyond Switzerland — a worldwide match, or its own outage note',
+    Boolean(worldSearch) && (worldItem ? /weltweit \(OpenStreetMap\)/.test(worldSearch.status) : worldOutage) && swissStillThere,
+    JSON.stringify(worldSearch).slice(0, 320),
+  );
+
+  // Choosing the worldwide place must move the map out of Switzerland and offer
+  // the “Karten an diesem Ort” chip with the number of seed sheets that document
+  // that point (the world maps cover it; no Swiss-only view did).
+  let worldChosen = null;
+  if (worldItem) {
+    await cdp.eval(
+      `[...document.querySelectorAll('#place-suggestions li button')].find((b) => /OpenStreetMap/.test(b.querySelector('.zh-suggestions__type')?.textContent || '') && /^Kairo/.test(b.querySelector('span')?.textContent || ''))?.click(); true`,
+    );
+    await sleep(1600);
+    worldChosen = await cdp.eval(`({
+      url: location.search,
+      input: document.querySelector('#place-input')?.value || '',
+      chip: document.querySelector('#place-action button')?.textContent || '',
+      markers: document.querySelectorAll('.map-marker').length,
+    })`);
+  }
+  check(
+    'a worldwide place opens the map there and counts the sheets that cover it',
+    worldChosen
+      ? /place=Kairo/.test(worldChosen.url) &&
+        /lat=3\d\./.test(worldChosen.url) &&
+        /lon=3\d\./.test(worldChosen.url) &&
+        /Karten an diesem Ort \(\d+\)/.test(worldChosen.chip) &&
+        worldChosen.markers > 0
+      : worldOutage,
+    JSON.stringify(worldChosen ?? worldSearch?.status ?? '').slice(0, 320),
+  );
+  await cdp.send('Page.navigate', { url: `${BASE_URL}/` });
+  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 0`, { label: 'reset after the world search' });
+
   /* --- 8q. Grundkarte (base map): farbig / grau / Luftbild -------------- */
   // The map offers the three documented swisstopo WMTS base layers. The chips
   // are built by map.js from BASE_LAYERS, so this section checks the real
   // tiles, the attribution, the shared URL state and the keyboard route.

