#!/usr/bin/env node
/** Reproduce the harness step for "Kairo" exactly (insertText after clearing). */
import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const BASE = 'http://127.0.0.1:8787';
const port = 9451;
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-'));
const child = spawn('/usr/bin/chromium', ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`, '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,960', 'about:blank'], { stdio: ['ignore', 'ignore', 'pipe'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) { for (let i = 0; i < 40; i++) { try { const res = await fetch(`http://127.0.0.1:${port}${p}`); if (res.ok) return res.json(); } catch {} await sleep(250); } throw new Error('no cdp'); }
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const reqs = []; const errs = [];
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
  else if (d.method === 'Network.responseReceived' && /api\/search|\/api\//.test(d.params.response.url)) reqs.push({ url: d.params.response.url, status: d.params.response.status });
  else if (d.method === 'Runtime.exceptionThrown') errs.push(d.params.exceptionDetails.exception?.description ?? d.params.exceptionDetails.text);
  else if (d.method === 'Runtime.consoleAPICalled' && d.params.type === 'error') errs.push(d.params.args.map((a) => a.value ?? a.description).join(' ').slice(0, 200));
};
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const evalJs = async (expression) => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.result?.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails).slice(0, 300));
  return r.result?.result?.value;
};
await send('Page.enable'); await send('Runtime.enable'); await send('Network.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 960, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: `${BASE}/?from=1546&to=1900` });
for (let i = 0; i < 60; i++) { if (await evalJs(`document.querySelectorAll('#result-list > *').length > 0`)) break; await sleep(300); }
await evalJs(`(() => { const n = document.querySelector('#place-input'); n.focus(); n.value = ''; n.dispatchEvent(new Event('input', { bubbles: true })); return true; })()`);
await send('Input.insertText', { text: 'Kairo' });
await sleep(2500);
console.log('input:', await evalJs(`document.querySelector('#place-input').value`));
console.log('status:', await evalJs(`document.querySelector('#place-status')?.textContent`));
console.log('items:', JSON.stringify(await evalJs(`[...document.querySelectorAll('#place-suggestions li')].map((li) => li.textContent)`)));
console.log('expanded:', await evalJs(`document.querySelector('#place-input').getAttribute('aria-expanded')`));
console.log('requests:', JSON.stringify(reqs));
console.log('errors:', JSON.stringify(errs));
child.kill();
